
public class Arrays_Intro2 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		//Arrays - multiple value in single variable
		
		int [] arr = new int[5];
		arr[0] =1;
		arr[1] =2;
		arr[2] =3;
		arr[3] =4;
		arr[4] =5;
	System.out.println(arr[2]);
	
	//another type fo array syntax
	
	int [] arr2 = {1,2,3,4,5};  //integer array
	
	System.out.println(arr2[4]);
	
	
	String[] r = {"Siva", "moni"};  //string array
	System.out.println(r[0]);
	
	}

}
